```javascript
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  CircleGeometry,
  BufferGeometry,
  LineBasicMaterial,
  LineLoop,
  Group,
  Mesh,
  Vector3,
} from 'three/webgpu';

import {
  ShaderNode,
  float,
  vec2,
  vec3,
  vec4,
  mix,
  step,
  smoothstep,
  length,
  abs,
  mod,
  fract,
  clamp,
  uv,
} from 'three/tsl';

import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // ── Panel dimensions ──
  const PW = 3.2;
  const PH = 2.2;
  const CORNER = 0.06;
  const BORDER = 0.006;
  const GRID_PITCH = 0.25;
  const GRID_LINE_W = 0.004;
  const MAX_DIST = Math.sqrt((PW / 2) ** 2 + (PH / 2) ** 2);

  // ── Shader node helpers ──
  function sdRoundRect(p, size, r) {
    const d = abs(p) - size + r;
    const dm = max(d, vec2(0.0));
    return length(dm) + min(max(d.x, d.y), 0.0) - r;
  }

  // ── Panel material ──
  const pos = vec2(
    mix(float(-PW / 2), float(PW / 2), uv.x),
    mix(float(-PH / 2), float(PH / 2), uv.y)
  );

  // radial gradient
  const gradT = clamp(length(pos) / float(MAX_DIST), 0.0, 1.0);
  const c1 = vec3(0.078, 0.078, 0.102);
  const c2 = vec3(0.043, 0.043, 0.063);
  const gradColor = mix(c1, c2, gradT);

  // hairline grid
  const distX = min(abs(mod(pos.x, float(GRID_PITCH))), abs(mod(pos.x, float(GRID_PITCH)) - float(GRID_PITCH)));
  const distY = min(abs(mod(pos.y, float(GRID_PITCH))), abs(mod(pos.y, float(GRID_PITCH)) - float(GRID_PITCH)));
  const gridLineX = 1.0 - smoothstep(0.0, float(GRID_LINE_W), distX);
  const gridLineY = 1.0 - smoothstep(0.0, float(GRID_LINE_W), distY);
  const gridLine = max(gridLineX, gridLineY);
  const gridCol = vec3(0.909, 0.925, 0.949);
  const gridAlpha = gridLine * 0.06;
  const insideColor = gradColor * (1.0 - gridAlpha) + gridCol * gridAlpha;

  // rounded rect mask & border
  const halfSize = vec2(float(PW / 2 - CORNER), float(PH / 2 - CORNER));
  const d = sdRoundRect(pos, halfSize, float(CORNER));
  const inside = float(d < 0.0);
  const borderDist = abs(d);
  const borderLine = 1.0 - smoothstep(0.0, float(BORDER / 2), borderDist);
  const borderCol = vec3(0.149, 0.149, 0.184);

  const finalColor = mix(insideColor, borderCol, borderLine);
  const alpha = inside + borderLine;

  const panelMat = new MeshBasicNodeMaterial();
  panelMat.colorNode = vec4(finalColor, alpha);
  panelMat.transparent = true;
  panelMat.side = 2;

  const panelGeo = new PlaneGeometry(PW, PH);
  const panelMesh = new Mesh(panelGeo, panelMat);
  group.add(panelMesh);

  // ── Ghost preview ──
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.6, 0.2, 0);
  group.add(ghostGroup);

  const ghostMat = new LineBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.30 });
  const ghostMatDim = new LineBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.22 });

  // wireframe card outline (rounded rectangle 1.1×1.4)
  const cardW = 1.1, cardH = 1.4, cardR = 0.04;
  const corners = [
    { cx: cardW / 2 - cardR, cy: cardH / 2 - cardR, start: 0, end: Math.PI / 2 },
    { cx: -cardW / 2 + cardR, cy: cardH / 2 - cardR, start: Math.PI / 2, end: Math.PI },
    { cx: -cardW / 2 + cardR, cy: -cardH / 2 + cardR, start: Math.PI, end: 3 * Math.PI / 2 },
    { cx: cardW / 2 - cardR, cy: -cardH / 2 + cardR, start: 3 * Math.PI / 2, end: 2 * Math.PI },
  ];
  const cardPts = [];
  corners.forEach(c => {
    for (let i = 0; i <= 6; i++) {
      const a = c.start + (c.end - c.start) * (i / 6);
      cardPts.push(new Vector3(c.cx + cardR * Math.cos(a), c.cy + cardR * Math.sin(a), 0));
    }
  });
  const cardGeo = new BufferGeometry().setFromPoints(cardPts);
  const cardLine = new LineLoop(cardGeo, ghostMat);
  ghostGroup.add(cardLine);

  // dial circle
  const dialRadius = 0.275;
  const dialGeo = new CircleGeometry(dialRadius, 24);
  const dialLine = new LineLoop(dialGeo, ghostMat);
  dialLine.position.set(0, 0.1, 0);
  ghostGroup.add(dialLine);

  // two text bars
  const barW = 0.7, barH = 0.06;
  const barY1 = -0.3, barY2 = -0.5;
  const makeBar = (y) => {
    const pts = [
      [-barW / 2, y],
      [barW / 2, y],
      [barW / 2, y + barH],
      [-barW / 2, y + barH],
      [-barW / 2, y],
    ].map(p => new Vector3(p[0], p[1], 0));
    const g = new BufferGeometry().setFromPoints(pts);
    return new LineLoop(g, ghostMatDim);
  };
  ghostGroup.add(makeBar(barY1));
  ghostGroup.add(makeBar(barY2));

  // ── Copy column ──
  const copyGroup = new Group();
  copyGroup.position.set(0.6, 0.0, 0);
  group.add(copyGroup);

  const headline = ctx.fontAtlas.createText('Your ledger is empty.', {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 400,
  });
  headline.position.set(0, 0.2, 0);
  copyGroup.add(headline);

  const body1 = ctx.fontAtlas.createText('Commissioned pieces and saved references', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 300,
  });
  body1.position.set(0, -0.05, 0);
  copyGroup.add(body1);

  const body2 = ctx.fontAtlas.createText('will appear here once you begin.', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 300,
  });
  body2.position.set(0, -0.15, 0);
  copyGroup.add(body2);

  // ── CTA Button ──
  const btnGroup = new Group();
  btnGroup.position.set(0.6, -0.7, 0);
  group.add(btnGroup);

  const btnW = 1.5, btnH = 0.36, btnR = 0.03;
  const btnPos = vec2(
    mix(float(-btnW / 2), float(btnW / 2), uv.x),
    mix(float(-btnH / 2), float(btnH / 2), uv.y)
  );
  const btnSDF = sdRoundRect(btnPos, vec2(btnW / 2 - btnR, btnH / 2 - btnR), float(btnR));
  const btnInside = float(btnSDF < 0.0);
  const btnGradT = (btnPos.y + btnH / 2) / btnH;
  const btnTop = vec3(1.0, 0.267, 0.314);
  const btnBot = vec3(0.757, 0.071, 0.122);
  const btnGrad = mix(btnBot, btnTop, btnGradT);

  const btnBorderDist = abs(btnSDF);
  const btnEdge = 1.0 - smoothstep(0.0, float(0.008), btnBorderDist);
  const emissiveColor = vec3(1.0, 0.165, 0.22);
  const emission = btnEdge * 1.5;

  const btnMat = new MeshStandardNodeMaterial();
  btnMat.colorNode = btnGrad;
  btnMat.emissiveNode = emissiveColor * emission;
  btnMat.transparent = true;

  const btnGeo = new PlaneGeometry(btnW, btnH);
  const btnMesh = new Mesh(btnGeo, btnMat);
  btnGroup.add(btnMesh);

  const btnLabel = ctx.fontAtlas.createText('BROWSE THE COLLECTION', {
    fontSize: 13,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 1.04,
  });
  btnLabel.position.set(0, 0, 0.001);
  btnGroup.add(btnLabel);

  // ── Ghost breathing ──
  const ghostMats = [ghostMat, ghostMatDim, ...ghostGroup.children.map(c => c.material)];
  const breathProxy = { opacity: 0.24 };
  const breathTL = gsap.to(breathProxy, {
    duration: 2.4,
    opacity: 0.34,
    yoyo: true,
    repeat: -1,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    onUpdate: () => {
      ghostMats.forEach(m => { if (m && m.opacity !== undefined) m.opacity = breathProxy.opacity; });
    },
  });

  // ── Mount animation ──
  const mountTL = gsap.fromTo(
    group,
    { opacity: 0, y: 0.2 },
    { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', delay: 0.1 }
  );

  // ── CTA hover ──
  btnGroup.userData.handlers = {
    mouseenter: () => {
      gsap.to(btnGroup, {
        scale: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
    mouseleave: () => {
      gsap.to(btnGroup, { scale: 1.0, duration: 0.12, ease: 'back.out(1.7)' });
    },
  };

  // ── Cleanup ──
  group.userData.cleanup = () => {
    mountTL.kill();
    breathTL.kill();
    delete btnGroup.userData.handlers;

    [panelMesh, btnMesh, cardLine, dialLine]
      .concat(ghostGroup.children.filter(c => c.isLine || c.isLineLoop))
      .concat([headline, body1, body2, btnLabel])
      .forEach(obj => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    // Dispose ghost geometry created manually
    cardGeo.dispose();
    dialGeo.dispose();
    // Additionally check for bar geometries
    ghostGroup.children.forEach(child => {
      if (child.isLineLoop && child.geometry !== cardGeo && child.geometry !== dialGeo) {
        child.geometry.dispose();
      }
    });
  };

  return group;
}
